    c(k) <= std_logic_vector(Switch13_out1_1(k));
  END GENERATE;

  rtxModK_tmp <= to_unsigned(16#00#, 8);

  rtxModK <= std_logic_vector(rtxModK_tmp);

  rtyModK_tmp <= to_unsigned(16#00#, 8);

  rtyModK <= std_logic_vector(rtyModK_tmp);

END rtl;

